__NUXT_JSONP__("/ar/how-to-apply/visa_overseas", (function(a){return {data:[{details:{slug:"ar",pageTitle:"التقدم بطلب للحصول على دراسة لمدة طويلة في الخارج | Mentor Language Institute",pageDescription:a,title:"التقدم بطلب للحصول على دراسة لمدة طويلة في الخارج",image:"\u002Fimages\u002Fvisa-overseas\u002Fvisa.jpg",category:[{title:a,list_content:[" شخص يعيش خارج الولايات المتحدة"," شخص يخطط للبقاء في أمريكا لأكثر من 90 يوما"," شخص يريد ان يتعلم في مدرسة لغة (مؤسسة تعليمية) في الولايات المتحدة."]},{title:"خطوات التطبيق\u002F التقديم",image:"\u002Fimages\u002Fvisa-overseas\u002Fsteps-en.jpg",ordered_content:[" تقديم على معهد منتور"," تقديم الوثائق"," تلقي I-20 الخاص بك"," طلب ​​التأشيرة \u002F مقابلة",". الحصول على في","- مغادرة الي الولايات المتحدة."],content:["وعادةتستغرق حوالي 3 أشهر من أجل الحصول على تأشيرة طالب والدراسة في الخارج. ويوصى بإعادة ترك أكبر قدر ممكن من الوقت لاستكمال عملية تقديم و الحصول علي تاشيرة. يرجى تقديم الطلب قبل ثلاثة أشهر على الأقل. يرجى إبلاغ موظفينا عند تقديم أقل من 3 أشهر قبل المغادرة."]},{title:"حول الخطوات بعد التطبيق",image:"\u002Fimages\u002Fvisa-overseas\u002Fmli-short-en.jpg",content:["بعد تطبيق الطلاب، يقوم نظام إملي بمعالجة التطبيق.\u003Cbr \u002F\u003Eيمكن للطلاب متابعة العملية التي يتم سردها على إملي."]},{title:"يقدم طلب على الإنترنت",content:["املأ المعلومات عن حالة التأشيرتك\u003Cbr \u002F\u003Eالاتصال بنا عبر iMLI لجميع الاستفسارات","تقديم من اسفل."]}],btn_label:"نموذج الطلب عبر الإنترنت",admission:{link:"\u002Far\u002Fadmission",content:["* يرجى توفير بطاقة الائتمان الخاصة بك."]},dir:"\u002Fvisa-overseas",path:"\u002Fvisa-overseas\u002Far",extension:".json",createdAt:"2026-10-22T16:31:31.335Z",updatedAt:"2025-05-26T12:06:28.029Z"}}],fetch:{},mutations:void 0}}("من هو المؤهل على التقدم بطلب للحصول على تأشيرة طالب؟")));